#include <bits/stdc++.h>
using namespace std;

int numSubarraysWithSum(vector<int>& nums, int goal) {
    unordered_map<int, int> seen;
    seen[0] = 1;
    int prefix = 0;
    long long total = 0;
    for (int v : nums) {
        prefix += v;
        auto it = seen.find(prefix - goal);
        if (it != seen.end()) total += it->second;
        ++seen[prefix];
    }
    return (int)total;
}

